```python
import itertools

def allocate_goods():
    people = ['Person 1', 'Person 2', 'Person 3']
    goods = ['Good A', 'Good B', 'Good C']
    values = {
        'Person 1': {'Good A': 45, 'Good B': 30, 'Good C': 25},
        'Person 2': {'Good A': 35, 'Good B': 40, 'Good C': 25},
        'Person 3': {'Good A': 50, 'Good B': 5, 'Good C': 45}
    }
    money = 5

    best_allocation = None
    best_score = float('-inf')

    for perm in itertools.permutations(goods):
        for money_split in itertools.product(range(money + 1), repeat=3):
            if sum(money_split) != money:
                continue

            allocation = {person: [] for person in people}
            money_allocation = {person: m for person, m in zip(people, money_split)}

            for i, good in enumerate(perm):
                allocation[people[i]].append(good)

            scores = [
                sum(values[person][good] for good in allocation[person]) + money_allocation[person]
                for person in people
            ]
            min_score = min(scores)

            if min_score > best_score:
                best_score = min_score
                best_allocation = (allocation, money_allocation)

    return best_allocation

result = allocate_goods()
print("Goods allocation:", result[0])
print("Money allocation:", result[1])
```

